CREATE TRIGGER IF NOT EXISTS site_records_immutable BEFORE UPDATE ON site_records WHEN OLD.kind IN ('revisions','handoffs') BEGIN SELECT RAISE(ABORT,'immutable_record'); END;
--> statement-breakpoint
CREATE TRIGGER IF NOT EXISTS site_handoff_revision BEFORE INSERT ON site_records WHEN NEW.kind='handoffs' BEGIN SELECT RAISE(ABORT,'invalid_handoff_revision') WHERE NOT EXISTS(SELECT 1 FROM site_records r WHERE r.project_id=NEW.project_id AND r.kind='revisions' AND r.version=NEW.version AND json_extract(r.payload,'$.context')=json_extract(NEW.payload,'$.snapshot.context')); SELECT RAISE(ABORT,'invalid_handoff_replacement') WHERE json_extract(NEW.payload,'$.supersedes_id') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM site_records h WHERE h.project_id=NEW.project_id AND h.kind='handoffs' AND h.id=json_extract(NEW.payload,'$.supersedes_id')); END;
